#!/usr/bin/env python3
"""Generate the sample G-code files used by ccsim's scripts and window.

Plain slicer-like output (start/end code, perimeters, a little infill) so
the emulator exercises heating, homing, extrusion, retraction, fans and
arcs. Run from this folder: python3 make_samples.py
"""
import math

FIL_AREA = math.pi * (1.75 / 2) ** 2


def e_for(length, width=0.45, height=0.2):
    return length * width * height / FIL_AREA


def header(name, nozzle, bed):
    return [
        f"; {name} — generated by make_samples.py for ccsim",
        "; generated by ccsim sample generator",
        "M73 P0 ; progress (ignored by ccos)",
        f"M140 S{bed}",
        f"M104 S{nozzle}",
        "G90",
        "M83",
        "G28",
        f"M190 S{bed}",
        f"M109 S{nozzle}",
        "G92 E0",
        "G1 Z2 F600",
        "; prime line",
        "G1 X10 Y5 F12000",
        "G1 Z0.3 F600",
        f"G1 X60 Y5 E{e_for(50, 0.6, 0.3):.5f} F1800",
        "G1 E-0.8 F2400 ; retract",
        "G1 Z1 F600",
    ]


def footer():
    return [
        "; end",
        "G1 E-1 F2400",
        "G91",
        "G1 Z5 F600",
        "G90",
        "G1 X200 Y250 F12000",
        "M104 S0",
        "M140 S0",
        "M107",
        "M84",
    ]


def square_layer(cx, cy, size, z, loops, speed, layer):
    # ElegooSlicer style marker: ccos (like the stock firmware) counts layers from it
    out = [f";LAYER:{layer}", f"; layer z={z:.2f}", f"G1 Z{z:.2f} F600", "G1 E0.8 F2400 ; unretract"]
    for k in range(loops):
        h = size / 2 - k * 0.45
        pts = [(cx - h, cy - h), (cx + h, cy - h), (cx + h, cy + h), (cx - h, cy + h), (cx - h, cy - h)]
        out.append(f"G1 X{pts[0][0]:.3f} Y{pts[0][1]:.3f} F12000")
        for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
            out.append(f"G1 X{x1:.3f} Y{y1:.3f} E{e_for(math.hypot(x1 - x0, y1 - y0)):.5f} F{speed * 60}")
    out.append("G1 E-0.8 F2400 ; retract")
    return out


def cube():
    lines = header("20 mm hollow cube, 5 layers", 210, 60)
    lines.append("M106 S180")
    for i in range(5):
        lines += square_layer(128, 128, 20, 0.2 + i * 0.2, 2, 120, i + 1)
    return lines + footer()


def disc():
    """Circles drawn with G2 arcs."""
    lines = header("Arc test: 3 rings with G2/G3, 3 layers", 210, 0)
    for i in range(3):
        z = 0.2 + i * 0.2
        lines += [f";LAYER:{i + 1}", f"G1 Z{z:.2f} F600", "G1 E0.8 F2400"]
        for r in (10, 15, 20):
            lines.append(f"G1 X{100 + r} Y100 F12000")
            circ = 2 * math.pi * r
            lines.append(f"G2 X{100 + r} Y100 I{-r} J0 E{e_for(circ):.5f} F4800")
        lines.append("G1 E-0.8 F2400")
    return lines + footer()


def speedtest():
    """Fast zig-zag travel + extrusion to stress step generation."""
    lines = header("Speed test: 300 mm/s zig-zag, 1 layer", 210, 0)
    lines += [";LAYER:1", "G1 Z0.2 F600", "G1 E0.8 F2400", "G1 X40 Y40 F18000"]
    y = 40.0
    for i in range(30):
        x = 200.0 if i % 2 == 0 else 40.0
        lines.append(f"G1 X{x:.1f} Y{y:.1f} E{e_for(160):.5f} F18000")
        y += 2.0
        lines.append(f"G1 X{x:.1f} Y{y:.1f} E{e_for(2):.5f} F18000")
    return lines + footer()


for name, fn in [("cube_20mm.gcode", cube), ("arc_rings.gcode", disc), ("speed_zigzag.gcode", speedtest)]:
    with open(name, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(fn()) + "\n")
    print(name)
